// CHECK-2P2-NEXT:    [[TMP14:%.*]] = bitcast <8 x i16> [[TMP10]] to <16 x i8>
// CHECK-2P2-NEXT:    [[TMP15:%.*]] = tail call ptr @llvm.riscv.esp.vst.128.ip(<16 x i8> [[TMP14]], ptr [[DST]], i32 16)
// CHECK-2P2-NEXT:    ret void
