void test_fft_ams_s16_ld_incp_uaup(void const *src, void *dst) {
    // Initialize UA_STATE, SAR_BYTES, SAR registers using builtins
    // Initialize SAR register (returns unsigned int for explicit state passing)
    unsigned int sar_in = __builtin_riscv_esp_movx_w_sar(0);

    // Initialize SAR_BYTES register (returns unsigned int for explicit state passing)
    unsigned int sar_bytes_in = __builtin_riscv_esp_movx_w_sar_bytes(0);

    // Initialize UA_STATE register by loading from memory
esp_ua_state_res_t ua_state_init;
  // Builtin signature: void*(void const *, int, void *)
  // Parameters: (src, offset, ua_state_out)
  // Returns: void* (updated pointer)
  // UA_STATE value is returned through output parameter
  ua_state_init.Ptr = __builtin_riscv_esp_ld_ua_state_ip(src, 16, &ua_state_init.UaState);

    // Load input vectors
esp_vld_res_t res_qx;
  res_qx.Ptr = __builtin_riscv_esp_vld_128_ip(src, 16, &res_qx.Val.V8);
esp_vld_res_t res_qy;
  res_qy.Ptr = __builtin_riscv_esp_vld_128_ip(src, 16, &res_qy.Val.V8);
esp_vld_res_t res_qw;
  res_qw.Ptr = __builtin_riscv_esp_vld_128_ip(src, 16, &res_qw.Val.V8);

    // Call FFT AMS LD.INCP.UAUP using wrapper function (Sel2 = 0)
    // Note: Rs1 should point to the Data to be loaded (after UA_STATE initialization)
esp_fft_ams_s16_ld_incp_uaup_res_t Res;
  // Call builtin with explicit phantom operands
  Res.Ptr = __builtin_riscv_esp_fft_ams_s16_ld_incp_uaup(
      res_qx.Val.V16, res_qy.Val.V16, res_qw.Val.V16, src, 0, 0, &Res.Qu, &Res.Qz, &Res.Qv, ua_state_init.UaState,
      &Res.UaState, sar_bytes_in, sar_in);

    // Store results back to memory using esp.vst.128.ip
    // Note: v8i16 and v16i8 have the same memory layout (128 bits), so we can use union for conversion
    union {
        esp_vec128_16_t V16;
        esp_vec128_t V8;
    } qz_conv, QvConv;

    qz_conv.V16 = Res.Qz;
    QvConv.V16 = Res.Qv;

    (void)__builtin_riscv_esp_vst_128_ip(Res.Qu, dst, 16);           // Store Qu (v16i8)
    (void)__builtin_riscv_esp_vst_128_ip(qz_conv.V8, dst, 16);  // Store Qz (v8i16 converted to v16i8)
    (void)__builtin_riscv_esp_vst_128_ip(QvConv.V8, dst, 16);  // Store Qv (v8i16 converted to v16i8)
}

